\captionsetup{labelformat=empty}
\caption{Figure 1.3 An inverted pyramid / funnel with seven horizontal bands, widest at top, narrowest at bottom. From top to bottom: Kingdom (widest, "most organisms, fewest shared characters"), Phylum/Division, Class, Order, Family, Genus, Species (narrow- est, "fewest organisms, most shared characters"). Two vertical arrows alongside: left arrow pointing up labelled "number of organisms increases"; right arrow point- ing down labelled "number of common characters increases".}
\end{figure}

